pub fn reservations_purpose() -> &'static str {
    "Reservation ledgers for tent, RV, cabin, group, backcountry, and day-use bookings entering campsite and permit review."
}

pub fn reservations_summary() -> String {
    let campsites = reservation_ledgers();
    let shard_total: u32 = campsites.iter().map(|item| item.shard).sum();
    let record_total: u32 = campsites.iter().map(|item| item.survey).sum();
    let pressure_total: u32 = campsites.iter().map(|item| item.pressure).sum();
    format!("reservations count={} shard={} rec={} pressure={}", campsites.len(), shard_total, record_total, pressure_total)
}

pub fn reservations_family_window(family: &str, limit: usize) -> Vec<ReservationLedger> {
    reservation_ledgers().into_iter().filter(|item| item.family == family).take(limit).collect()
}

pub fn reservations_weighted_total(seed: u32) -> u64 {
    reservation_ledgers().into_iter().enumerate().map(|(index, item)| {
        let bias = (seed as u64 + index as u64 % 31) + 1;
        bias * (item.shard as u64 + item.survey as u64 * 3 + item.pressure as u64 * 5)
    }).sum()
}

pub fn reservations_nearest(shard: u32, survey: u32) -> Option<ReservationLedger> {
    reservation_ledgers().into_iter().min_by_key(|item| {
        let a = item.shard.abs_diff(shard) as u64;
        let b = item.survey.abs_diff(survey) as u64;
        a * 7 + b * 3 + item.pressure as u64
    })
}

pub fn reservations_note_digest(limit: usize) -> Vec<String> {
    reservation_ledgers().into_iter().take(limit).map(|item| format!("{}:{}:{}", item.key, item.family, item.note)).collect()
}
